def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    low = blob.lower()
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"] + EDITORIAL_BAN:
        if marker in low:
            problems.append(f"  {name}: banned phrase '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.199.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.198.0"' not in init:
        sys.exit("ABORT: not at v3.198.0.")
    if "purchase_orders" not in data:
        sys.exit("ABORT: purchase_orders module not found in data file.")

    problems = _validate("PROC5", LESSONS_P5, QUESTIONS_P5, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_P5))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — PROC5 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_P5)
    print(f"PROC 5 v3: {len(LESSONS_P5)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_P5):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["purchase_orders"]["lessons"] = LESSONS_P5
    data["purchase_orders"]["questions"] = bank
    data["purchase_orders"]["desc"] = ("The Purchase Order in ZhiftERP: the field walk — the demand trace, sourced rates, per-row Required By dates, warehouses, and the supplier confirmation; submission effects — incoming quantities raising projected stock and standing the trigger down, the %received and %billed execution basis, and what submission does not do; multi-drop schedules with split rows, the band-across-the-order rule, the incoming planning read, and the chase ladder; the amendment taxonomy — rate changes under award governance, quantity increases through the screen, schedule movements with parties, and the Closed status; the purchase tax side, withholding located at payment, and supplier advances with the exposure read; and the order book's six reads including stale-order hygiene as stock-out prevention.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.198.0"', '"3.199.0"'))
    print("  data: PROCUREMENT 5 lessons + bank REPLACED (style v3, textbook manual register)")
    print("wrote __version__ -> 3.199.0")


if __name__ == "__main__":
    main()
